/**
 * Artwork for the 38 achievements, one flat set drawn to sit on the dark tile.
 *
 * Each icon carries its own viewBox because they were drawn separately and then
 * normalised: every one is cropped to its own bounding box and given the same
 * padding, so a star and a clapperboard take up the same optical space. Before
 * that they ranged from 60 to 176 per cent of the median, which is why the star
 * looked small next to its neighbours.
 *
 * Colours come from the app's own palette. Nothing here is dark enough to sink
 * into the #1a2535 tile except a few interior details that are enclosed by a
 * lighter shape and never touch it.
 *
 * Not the same family as the emotion drops in ./emotion-icons: those are motifs
 * inside one shared teardrop, these are free-standing objects. An achievement
 * should not read as a feeling.
 */

export interface AchievementIcon {
  viewBox: string;
  parts: { fill: string; d: string }[];
}

